INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Kaufvertrag für Software immer schriftlich sein muss. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Mündliche Verträge sind auch gültig"}, {"text": "Ja", "correct": false, "because": "Schriftform nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich Hardware für die Firma kaufe?', 3, '[{"text": "Klarheit der Bedingungen", "correct": true, "because": "Vermeidet Streitigkeiten"}, {"text": "Schnellste Lieferung", "correct": false, "because": "Sekundär"}, {"text": "Farbe der Geräte", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einem Kaufvertrag für IT-Produkte?', 5, '[{"text": "Kaufpreis", "correct": true, "because": "Definiert Kosten"}, {"text": "Lieferbedingungen", "correct": true, "because": "Regelt Übergabe"}, {"text": "Bürogestaltung", "correct": false, "because": "Kein Vertragsbestandteil"}, {"text": "Werbematerial", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Kaufvertrag benötigt eine genaue Produktbeschreibung. b) Gewährleistung ist immer ausgeschlossen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gewährleistung ist gesetzlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich einen Vertrag für Server abschließe?', 4, '[{"text": "Garantieleistungen", "correct": false, "because": "Schützt bei Defekten"}, {"text": "Lieferfristen", "correct": false, "because": "Wichtig für Planung"}, {"text": "Verkäuferimage", "correct": true, "because": "Kein rechtlicher Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Kaufvertrag ohne Preisangabe gültig ist?', 2, '[{"text": "Nein", "correct": true, "because": "Preis ist wesentlicher Bestandteil"}, {"text": "Ja", "correct": false, "because": "Preisangabe erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Kaufvertrag für Software?', 3, '[{"text": "Rechtssicherheit", "correct": true, "because": "Klare Regeln für beide Seiten"}, {"text": "Schnelle Installation", "correct": false, "because": "Kein Vertragsziel"}, {"text": "Mehr Features", "correct": false, "because": "Kein rechtlicher Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sind bei einem Kaufvertrag für IT-Dienstleistungen wichtig?', 5, '[{"text": "Leistungsumfang", "correct": true, "because": "Definiert Dienstleistung"}, {"text": "Zahlungsbedingungen", "correct": true, "because": "Regelt Bezahlung"}, {"text": "Büroausstattung", "correct": false, "because": "Kein Vertragsbestandteil"}, {"text": "Marketingziele", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Gewährleistung gilt für zwei Jahre. b) Mängel müssen sofort gemeldet werden. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Mängel haben Prüfungsfrist"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen Kaufvertrag für Laptops?', 4, '[{"text": "Produktspezifikation", "correct": false, "because": "Definiert Kaufgegenstand"}, {"text": "Lieferdatum", "correct": false, "because": "Wichtig für Planung"}, {"text": "Verkäuferhobbys", "correct": true, "because": "Kein Vertragsbestandteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Kaufvertrag ohne Unterschrift ungültig?', 2, '[{"text": "Nein", "correct": true, "because": "Mündliche Verträge sind möglich"}, {"text": "Ja", "correct": false, "because": "Schriftform nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rechte habe ich bei einem Kaufvertrag für defekte Hardware?', 4, '[{"text": "Nachbesserung", "correct": true, "because": "Teil der Gewährleistung"}, {"text": "Sofortige Rückgabe", "correct": false, "because": "Nur nach Fristsetzung"}, {"text": "Neues Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Kaufvertrag immer online abgeschlossen werden kann. Stimmt das?', 2, '[{"text": "Ja", "correct": true, "because": "Online-Verträge sind gültig"}, {"text": "Nein", "correct": false, "because": "Auch offline möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um einen Kaufvertrag für Cloud-Dienste abzusichern?', 3, '[{"text": "Service-Level-Agreement", "correct": true, "because": "Definiert Leistungsstandards"}, {"text": "Neue Hardware", "correct": false, "because": "Nicht relevant"}, {"text": "Bunte Verträge", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Kaufvertrag regelt Eigentumsübergang. b) Er muss immer notariell sein.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Notar nicht erforderlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein klarer Kaufvertrag für IT-Produkte?', 5, '[{"text": "Rechtliche Klarheit", "correct": true, "because": "Vermeidet Streit"}, {"text": "Verbindliche Lieferung", "correct": true, "because": "Sichert Termine"}, {"text": "Höhere Leistung", "correct": false, "because": "Kein Vertragsfaktor"}, {"text": "Bessere Designs", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich einen Kaufvertrag für Netzwerkausrüstung abschließe?', 3, '[{"text": "Garantiebedingungen", "correct": false, "because": "Schützt bei Defekten"}, {"text": "Lieferumfang", "correct": false, "because": "Definiert Produkt"}, {"text": "Verkäufergröße", "correct": true, "because": "Kein rechtlicher Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Kaufvertrag ohne Zustimmung gültig sein?', 3, '[{"text": "Nein", "correct": true, "because": "Zustimmung ist erforderlich"}, {"text": "Ja", "correct": false, "because": "Vertrag braucht Einigung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Kaufvertrag für Software Lizenzen umfasst?', 2, '[{"text": "Ja", "correct": true, "because": "Lizenzen sind oft Teil"}, {"text": "Nein", "correct": false, "because": "Lizenzen häufig enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend, wenn ich einen Kaufvertrag für IT-Dienstleistungen abschließe?', 4, '[{"text": "Leistungsbeschreibung", "correct": true, "because": "Definiert Dienstleistung"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Sekundär"}, {"text": "Büroausstattung", "correct": false, "because": "Irrelevant"}]');
